78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /**
81	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
82	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
83	     */
84	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
85	
86	    /**
87	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
88	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
89	     */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /**
97	     * Source of the monotonically increasing {@code seq} stamped on each {@link OwnerCreatedEvent}.
98	     * Incremented once per successful create so the emitted events form a gap-free, strictly increasing
99	     * sequence across all creates handled by this application instance.
100	     */
101	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
102	
103	    /** Request header carrying the client-supplied idempotency key for owner creation. */
104	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
105	
106	    /**
107	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that create originally
108	     * produced for it. A repeated create carrying a key found here returns that same owner instead of
109	     * creating a duplicate, making owner creation idempotent with respect to the key.
110	     */
111	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
112	
