164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
167	        String idempotencyKey = currentIdempotencyKey();
168	        if (idempotencyKey != null) {
169	            Integer existingId = this.ownersByIdempotencyKey.get(idempotencyKey);
170	            if (existingId != null) {
171	                Owner existing = this.clinicService.findOwnerById(existingId);
172	                if (existing != null) {
173	                    return new ResponseEntity<>(toOwnerDtoWithBulkWarning(existing), HttpStatus.OK);
174	                }
175	            }
176	        }
177	        List<String> missingFields = new ArrayList<>();
178	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
179	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
180	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
181	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
182	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
183	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
184	        String normalizedAddress = hasStructuredAddress
185	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
186	            : normalizedFlatAddress;
187	        requireNonBlank(missingFields, "address", normalizedAddress);
188	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
189	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
190	        if (!missingFields.isEmpty()) {
191	            throw new MissingRequiredFieldsException(missingFields);
192	        }
193	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
194	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
195	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
196	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
197	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
198	        requireDailyLimitNotReached(registrationDate);
199	        requireCityBelowCapacity(ownerFieldsDto.getCity());
200	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
201	        ownerFieldsDto.setTelephone(normalizedTelephone);
202	        if (ownerFieldsDto.getEmail() != null) {
203	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
204	        }
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        HttpHeaders headers = new HttpHeaders();
207	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
208	        owner.setAddress(normalizedAddress);
209	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
210	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
211	            ? normalizedAddressLine2 : null);
212	        owner.setRegistrationDate(registrationDate);
213	        owner.setMemberId(buildMemberId(owner, normalizedTelephone));
214	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
215	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
216	        requireUniqueIdentity(owner);
217	        markPossibleDuplicate(owner, sharesHousehold);
218	        this.clinicService.saveOwner(owner);
219	        if (idempotencyKey != null) {
220	            this.ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
221	        }
222	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
223	        AUDIT.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
224	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
225	            ownerDto.getMembershipLevel());
226	        OwnerCreatedEvent event = OwnerCreatedEvent.forCreatedOwner(
227	            OWNER_CREATED_SEQUENCE.incrementAndGet(), owner, ownerDto.getMembershipLevel());
228	        AUDIT.info(this.objectMapper.writeValueAsString(event));
229	        headers.setLocation(UriComponentsBuilder.newInstance()
230	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
231	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
232	    }
