234	    /**
235	     * Returns the {@code Idempotency-Key} header of the request in progress, or {@code null} when the
236	     * header is absent, blank, or there is no active servlet request. The generated {@link OwnersApi}
237	     * signature carries no header parameter, so it is read from the current request context.
238	     */
239	    private static String currentIdempotencyKey() {
240	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
241	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
242	            if (key != null && !key.isBlank()) {
243	                return key;
244	            }
245	        }
246	        return null;
247	    }
