342	    /**
343	     * Builds the owner's unified {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION}
344	     * is the region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'})
345	     * via {@link OwnerMapper#toRegion}; {@code FY} is the 2-digit fiscal year of the owner's
346	     * business-day-adjusted {@code registrationDate}; {@code HASH8} is the first 8 upper-case hex
347	     * characters of the SHA-256 digest of {@code normalizedTelephone + lastName}; and {@code CHK} is a
348	     * single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D9}).
349	     *
350	     * <p>When the computed id collides with an existing owner's {@code memberId}, it is de-duplicated by
351	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g.
352	     * {@code NSW261A2B3C4D9-2}); the de-duplicated id is returned. Absent a collision the base id is
353	     * returned unchanged.
354	     *
355	     * @param owner the owner being created, with its region-determining postcode/city and
356	     *              registrationDate populated
357	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
358	     * @return the (de-duplicated) member id for the owner being created
359	     */
360	    private String buildMemberId(Owner owner, String normalizedTelephone) {
361	        String region = ownerMapper.toRegion(owner);
362	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
363	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
364	        String core = region + fy + hash8;
365	        String baseId = core + luhnCheckDigit(core);
366	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
367	            .map(Owner::getMemberId)
368	            .filter(java.util.Objects::nonNull)
369	            .collect(java.util.stream.Collectors.toSet());
370	        if (!existingIds.contains(baseId)) {
371	            return baseId;
372	        }
373	        int n = 2;
374	        while (existingIds.contains(baseId + "-" + n)) {
375	            n++;
376	        }
377	        return baseId + "-" + n;
378	    }
379	
380	    /**
381	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in {@code value};
382	     * non-digit characters are ignored. Used to append the {@code CHK} segment to a member id's
383	     * {@code <REGION><FY><HASH8>} core.
384	     */
385	    private static int luhnCheckDigit(String value) {
386	        int sum = 0;
387	        boolean dbl = true;
388	        for (int i = value.length() - 1; i >= 0; i--) {
389	            char c = value.charAt(i);
390	            if (c < '0' || c > '9') {
391	                continue;
392	            }
393	            int d = c - '0';
394	            if (dbl) {
395	                d *= 2;
396	                if (d > 9) {
397	                    d -= 9;
398	                }
399	            }
400	            sum += d;
401	            dbl = !dbl;
402	        }
403	        return (10 - (sum % 10)) % 10;
404	    }
405	
406	    /**
407	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
408	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
409	     */
410	    private static String sha256Hex8(String value) {
411	        try {
412	            byte[] digest = MessageDigest.getInstance("SHA-256")
413	                .digest(value.getBytes(StandardCharsets.UTF_8));
414	            StringBuilder sb = new StringBuilder();
415	            for (byte b : digest) {
416	                sb.append(String.format("%02X", b));
417	            }
418	            return sb.substring(0, 8);
419	        }
420	        catch (NoSuchAlgorithmException e) {
421	            throw new IllegalStateException("SHA-256 not available", e);
422	        }
423	    }
