451	    /**
452	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
453	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
454	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
455	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
456	     * {@code "+61412345678"}.
457	     *
458	     * @param telephone the raw telephone value from the request
459	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
460	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
461	     */
462	    private static String normalizeTelephone(String telephone) {
463	        String e164 = toE164(telephone);
464	        if (e164 == null) {
465	            throw new InvalidFieldValueException("telephone",
466	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
467	        }
468	        return e164;
469	    }
470	
471	    /**
472	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
473	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
474	     * owners' stored numbers when detecting duplicates.
475	     */
476	    private static String toE164(String telephone) {
477	        if (telephone == null) {
478	            return null;
479	        }
480	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
481	        String digits;
482	        if (cleaned.startsWith("+")) {
483	            digits = cleaned.substring(1);
484	        } else {
485	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
486	            digits = "61" + national;
487	        }
488	        if (!digits.matches("[0-9]{8,15}")) {
489	            return null;
490	        }
491	        if (!hasValidNationalLength(digits)) {
492	            return null;
493	        }
494	        return "+" + digits;
495	    }
496	
497	    /**
498	     * Checks the national-number length against the country code for the country codes that pin one.
499	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
500	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
501	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
502	     */
503	    private static boolean hasValidNationalLength(String digits) {
504	        if (digits.startsWith("61")) {
505	            return digits.length() - 2 == 9;
506	        }
507	        if (digits.startsWith("1")) {
508	            return digits.length() - 1 == 10;
509	        }
510	        return true;
511	    }
