514	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
515	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
516	     *
517	     * @param email the raw email value from the request (already known to be non-null)
518	     * @return the lower-cased email to be stored and returned
519	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
520	     */
521	    private static String normalizeEmail(String email) {
522	        String trimmed = email.trim();
523	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
524	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
525	        }
526	        String canonical = trimmed.toLowerCase(Locale.ROOT);
527	        String domain = canonical.substring(canonical.indexOf('@') + 1);
528	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
529	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
530	        }
531	        return canonical;
532	    }
