579	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
580	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
581	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
582	        ownerDto.setCapacityWarning(approachingCityCapacity(owner.getCity()));
583	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
584	        ownerDto.setMembershipPoints(points);
