589	    /**
590	     * Caps the owner's {@code membershipLevel} so it cannot exceed one above the current maximum
591	     * membership level among the other members of its household (existing owners carrying the same
592	     * {@code householdId}, excluding the owner itself and any soft-deleted owner). When the household
593	     * has no other member — including when the owner has no {@code householdId} — no cap applies and
594	     * {@code level} is returned unchanged. Each household member's level is its own base level (points
595	     * mapped to a level for its real household size), so the cap does not depend on other capped
596	     * values.
597	     *
598	     * @param owner the owner whose membership level is being computed
599	     * @param level the owner's uncapped membership level derived from its membership points
600	     * @return the membership level capped at {@code maxHouseholdMemberLevel + 1}, or {@code level}
601	     *         when the owner has no other household member
602	     */
603	    private int capMembershipLevel(Owner owner, int level) {
604	        String householdId = owner.getHouseholdId();
605	        if (householdId == null) {
606	            return level;
607	        }
608	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
609	            .filter(existing -> !isDeleted(existing))
610	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
611	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
612	            .map(this::membershipLevelForOwner)
613	            .max(Integer::compareTo)
614	            .orElse(null);
615	        if (maxMemberLevel == null) {
616	            return level;
617	        }
618	        return Math.min(level, maxMemberLevel + 1);
619	    }
