621	    /**
622	     * Computes an existing household member's membership level: its membership points for its real
623	     * household size mapped to the numeric level. Used to establish the household's current maximum
624	     * level when capping a new owner's level.
625	     */
626	    private int membershipLevelForOwner(Owner owner) {
627	        int points = OwnerMapper.membershipPointsFor(owner, householdSize(owner.getHouseholdId()));
628	        return OwnerMapper.membershipLevelFor(points);
629	    }
