673	    /**
674	     * Fixed list of public holidays. A registration date landing on one of these dates is rolled
675	     * forward, just like a weekend, until it reaches a non-holiday business day.
676	     */
677	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
678	        LocalDate.of(2026, 1, 1),
679	        LocalDate.of(2026, 1, 26),
680	        LocalDate.of(2026, 4, 25),
681	        LocalDate.of(2026, 12, 25),
682	        LocalDate.of(2026, 12, 28));
683	
684	    /**
685	     * Rolls {@code date} forward to a business day: while it falls on a Saturday, Sunday, or a listed
686	     * public holiday it advances one day at a time until it reaches a non-holiday weekday. Applied to
687	     * the effective registration date (whether supplied in the request or defaulted to the server date)
688	     * so a weekend or holiday registration is recorded on the next business day, and every value derived
689	     * from the registration date uses the adjusted date.
690	     *
691	     * @param date the effective registration date (supplied or defaulted), never {@code null}
692	     * @return the same date, or the next non-holiday business day when {@code date} is a weekend or holiday
693	     */
694	    private static LocalDate toBusinessDay(LocalDate date) {
695	        LocalDate adjusted = date;
696	        while (isWeekend(adjusted) || PUBLIC_HOLIDAYS.contains(adjusted)) {
697	            adjusted = adjusted.plusDays(1);
698	        }
699	        return adjusted;
700	    }
