702	    /** Whether {@code date} falls on a Saturday or Sunday. */
703	    private static boolean isWeekend(LocalDate date) {
704	        DayOfWeek day = date.getDayOfWeek();
705	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
706	    }
