708	    /** Matches a well-formed postcode: exactly four decimal digits. */
709	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
710	
711	    /**
712	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
713	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
714	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
715	     * present here and accepts any well-formed postcode.
716	     */
717	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
718	        "NSW", new int[] {2000, 2099},
719	        "VIC", new int[] {3000, 3099},
720	        "QLD", new int[] {4000, 4099});
721	
722	    /**
723	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
724	     * optional, so the request contract stays backward-compatible). When present it must be exactly
725	     * four digits and, for a city whose region is known, fall within that region's inclusive range
726	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
727	     * postcode. A malformed or out-of-range value is rejected with a 400.
728	     *
729	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
730	     * @param city the owner's city, used to look up the region whose range constrains the postcode
731	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
732	     */
733	    private void validatePostcode(String postcode, String city) {
734	        if (postcode == null) {
735	            return;
736	        }
737	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
738	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
739	        }
740	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
741	        int[] range = REGION_POSTCODES.get(region);
742	        if (range == null) {
743	            return;
744	        }
745	        int value = Integer.parseInt(postcode);
746	        if (value < range[0] || value > range[1]) {
747	            throw new InvalidFieldValueException("postcode",
748	                "Postcode must be valid for the city's region " + region);
749	        }
750	    }
