838	     * duplicate. An owner with no {@code postcode} never matches, since the soft match is keyed on it.
839	     *
840	     * @param owner the incoming owner, with its telephone, email and postcode populated
841	     * @param sharesHousehold whether the request opted in as a declared household member
842	     */
843	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
844	        owner.setPossibleDuplicate(false);
845	        owner.setPossibleDuplicateOf(null);
846	        if (sharesHousehold) {
847	            return;
848	        }
849	        String postcode = owner.getPostcode();
850	        if (postcode == null || postcode.isBlank()) {
851	            return;
852	        }
853	        String soundex = OwnerIdentity.soundex(owner.getLastName());
854	        String identityKey = ownerMapper.toIdentityKey(owner);
855	        this.clinicService.findAllOwners().stream()
856	            .filter(existing -> !isDeleted(existing))
857	            .filter(existing -> postcode.equals(existing.getPostcode()))
858	            .filter(existing -> soundex.equals(OwnerIdentity.soundex(existing.getLastName())))
859	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
860	            .min(java.util.Comparator.comparing(Owner::getId))
861	            .ifPresent(match -> {
862	                owner.setPossibleDuplicate(true);
863	                owner.setPossibleDuplicateOf(match.getId());
864	            });
865	    }
866	
867	    /**
868	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
869	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
870	     * comparisons are case-insensitive.
871	     */
872	    private static String normalizeForHousehold(String value) {
873	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
874	    }
875	
876	    /**
877	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
878	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
879	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
880	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
881	     * value normalizes to the empty string, so the required-field check rejects an address that is
882	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
883	     *
884	     * @param address the raw address value from the request (may be {@code null})
885	     * @return the normalized address, or the empty string when blank after normalization
886	     */
887	    private static String normalizeAddress(String address) {
888	        if (address == null) {
889	            return "";
890	        }
891	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
892	        if (collapsed.isEmpty()) {
893	            return "";
894	        }
895	        String[] tokens = collapsed.split(" ");
896	        StringBuilder sb = new StringBuilder();
897	        for (String token : tokens) {
898	            String expanded = switch (token) {
899	                case "ST" -> "STREET";
900	                case "RD" -> "ROAD";
901	                case "AVE" -> "AVENUE";
902	                default -> token;
903	            };
904	            if (sb.length() > 0) {
905	                sb.append(' ');
906	            }
907	            sb.append(expanded);
908	        }
909	        return sb.toString();
910	    }
911	
912	    /**
913	     * Composes the stored/returned {@code address} from the normalized structured lines: the
914	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
915	     * appended when {@code addressLine2} is present (non-empty). Both arguments are already
916	     * normalized via {@link #normalizeAddress(String)}.
917	     *
918	     * @param normalizedAddressLine1 the normalized first address line (non-empty)
919	     * @param normalizedAddressLine2 the normalized second address line, or the empty string when absent
920	     * @return the composed address string
921	     */
922	    private static String composeAddress(String normalizedAddressLine1, String normalizedAddressLine2) {
923	        if (normalizedAddressLine2.isEmpty()) {
924	            return normalizedAddressLine1;
925	        }
926	        return normalizedAddressLine1 + " " + normalizedAddressLine2;
927	    }
928	
929	    /**
930	     * Derives the stable household identifier for an owner from its last name and postcode as the
931	     * upper-cased first 12 hex characters of the SHA-256 digest of
932	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
933	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
934	     * identifier is a deterministic function of the normalized last name and postcode, owners that
935	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
936	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
937	     * postcode and there is then nothing to key on.
938	     *
939	     * @param lastName the owner's last name (already validated non-blank)
940	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
941	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
942	     */
943	    private static String householdIdFor(String lastName, String postcode) {
944	        if (postcode == null || postcode.isBlank()) {
945	            return null;
946	        }
947	        String normalizedLastName = normalizeForHousehold(lastName);
948	        try {
949	            byte[] digest = MessageDigest.getInstance("SHA-256")
950	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
951	            StringBuilder sb = new StringBuilder();
952	            for (byte b : digest) {
953	                sb.append(String.format("%02X", b));
954	            }
955	            return sb.substring(0, 12);
956	        }
957	        catch (NoSuchAlgorithmException e) {
958	            throw new IllegalStateException("SHA-256 not available", e);
959	        }
960	    }
961	}
